    "plus5": "取得時隨機獲得三個永久能力願望（生命、魔力、攻防、恢復或六維等能力）。戰鬥三願每場各 1 次：「生存願」受傷後生命 ≤30% 時回復 30% 最大生命（遺物治癒冷卻 5 秒）；「魔力願」魔力 ≤20% 時回復 30% 最大魔力；「勝利願」開戰 10 秒後直接攻擊與傷害法術 ×1.25，持續 10 秒。",
