    "ascend": "【願望成真】取得時隨機獲得三個永久能力願望（生命、魔力、攻防、恢復或六維等能力）。戰鬥三願每場各 1 次：「生存願」受到致死傷害時免死、回滿生命並無敵 3 秒（需本件治癒冷卻已好）；「魔力願」魔力 ≤20% 時回滿魔力；「勝利願」開戰 10 秒後傷害 ×2，持續 15 秒。",
    "ascend5": "【三願常存】三種戰鬥願望全部用完後，經20秒一併補回各1次；勝利願補回即發動，另外兩願等待各自條件。勝利願×3、持續15秒；生存願仍受至少5 秒治癒冷卻，不能靠換裝或新一波敵人重置。",
